body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;box-sizing:border-box;font-family: 'Be Vietnam Pro', system-ui,sans-serif}
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@500;600;700;800&display=swap');

.cb-09 {
  --bg: #f7f5f2;
  --accent: #111827;
  --ink: #ffffff;
  --ok: #15803d;
  --badge: #f59e0b;
  --badge-ink: #1c1206;
  --dx: 6.5rem;
  --dy: 3.2rem;
  --radius: .85rem;
  --sans: "Plus Jakarta Sans",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
  width: 100%;
  min-height: 100vh;
  min-height: 100svh;
  display: block;
  background: var(--bg);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
}

@supports (color: oklch(50% 0 0)) {
  .cb-09 {
    --bg: oklch(97% .006 85);
    --accent: oklch(20% .015 265);
    --ok: oklch(52% .14 148);
    --badge: oklch(78% .16 74);
  }
}

@media (prefers-color-scheme: dark) {
  .cb-09:not([data-theme="light"]) {
    --bg: #0c0b0a;
    --accent: #f5f4f0;
    --ink: #0e0e10;
    --ok: #22c55e;
  }
}

.cb-09[data-theme="dark"] {
  --bg: #0c0b0a;
  --accent: #f5f4f0;
  --ink: #0e0e10;
  --ok: #22c55e;
}

.cb-09,
.cb-09 *,
.cb-09 *::before,
.cb-09 *::after {
  box-sizing: border-box;
}

.cb-09__stage {
  min-height: 100vh;
  min-height: 100svh;
  display: grid;
  place-items: center;
  padding: clamp(1.5rem,6vw,4rem);
}

.cb-09__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.cb-09__btn {
  position: relative;
  cursor: pointer;
  display: grid;
  align-items: center;
  min-height: 3.4rem;
  padding: 0 1.8rem;
  border: 0;
  border-radius: var(--radius);
  font: inherit;
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -.01em;
  color: var(--ink);
  background: var(--accent);
  box-shadow: 0 12px 26px -14px color-mix(in oklab,var(--accent) 85%,transparent);
  transition: translate .22s cubic-bezier(.16,1,.3,1), background-color .35s ease;
}

.cb-09__slot {
  grid-area: 1/1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .6rem;
  opacity: 0;
  scale: .94;
  transition: opacity .2s ease, scale .3s cubic-bezier(.16,1,.3,1);
}

.cb-09__slot svg {
  width: 1.2rem;
  height: 1.2rem;
  flex: none;
}

.cb-09__btn[data-state="idle"] .cb-09__slot--idle,
.cb-09__btn[data-state="done"] .cb-09__slot--done {
  opacity: 1;
  scale: 1;
}

.cb-09__btn[data-state="done"] {
  background: var(--ok);
}

.cb-09__btn:hover {
  translate: 0 -2px;
}

.cb-09__btn:active {
  translate: 0 1px;
  scale: .99;
}

.cb-09__btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.cb-09__fly {
  position: absolute;
  left: 1.8rem;
  top: 50%;
  margin-top: -.6rem;
  width: 1.2rem;
  height: 1.2rem;
  opacity: 0;
  pointer-events: none;
  color: var(--ink);
}

.cb-09__fly svg {
  width: 100%;
  height: 100%;
}

.cb-09__btn.is-fly .cb-09__fly {
  animation: cb-09-fly .72s cubic-bezier(.32,.06,.6,1) forwards;
}

@keyframes cb-09-fly {
  0% {
    translate: 0 0;
    scale: 1;
    opacity: 1;
  }

  55% {
    translate: calc(var(--dx) * .6) calc(var(--dy) * -1);
    scale: .72;
    opacity: 1;
  }

  100% {
    translate: var(--dx) -.4rem;
    scale: .25;
    opacity: 0;
  }
}

.cb-09__badge {
  position: absolute;
  top: -.55rem;
  right: -.55rem;
  min-width: 1.65rem;
  height: 1.65rem;
  padding: 0 .35rem;
  display: grid;
  place-items: center;
  border-radius: 999px;
  font-size: .8125rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--badge-ink);
  background: var(--badge);
  box-shadow: 0 2px 8px -2px color-mix(in oklab,var(--badge) 80%,transparent);
}

.cb-09__badge.is-bump {
  animation: cb-09-bump .5s cubic-bezier(.16,1,.3,1);
}

@keyframes cb-09-bump {
  0% {
    scale: 1;
  }

  35% {
    scale: 1.35;
    rotate: -6deg;
  }

  100% {
    scale: 1;
    rotate: 0deg;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cb-09__btn,
    .cb-09__slot {
    transition: none;
  }

  .cb-09__fly {
    display: none;
