  font-size: .8125rem;
  font-weight: 600;
  color: var(--muted);
  white-space: nowrap;
}

.cb-12__yes {
  cursor: pointer;
  white-space: nowrap;
  border: 0;
  border-radius: var(--radius);
  min-height: 2.75rem;
  padding: 0 1.1rem;
  font: inherit;
  font-size: .875rem;
  font-weight: 700;
  color: var(--danger-ink);
  background: var(--danger);
  box-shadow: 0 8px 18px -12px color-mix(in oklab,var(--danger) 85%,transparent);
  transition: background-color .2s ease, translate .2s cubic-bezier(.16,1,.3,1);
}

.cb-12__yes:hover {
  background: color-mix(in oklab,var(--danger) 85%,black);
  translate: 0 -1px;
}

.cb-12__yes:active {
  translate: 0 1px;
}

.cb-12__yes:focus-visible {
  outline: 2px solid var(--danger);
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .cb-12__shell,
    .cb-12__confirmInner,
    .cb-12__lid,
    .cb-12__yes,
    .cb-12__trigger {
    transition: none;
  }
}

@media (forced-colors: active) {
  .cb-12__shell {
    border: 1px solid ButtonText;
  }

  .cb-12__yes {
    background: Highlight;
    color: HighlightText;
  }
}

