.btn-11 {
  --accent: oklch(0.7 0.15 230);
  font-family: 'Segoe UI',system-ui,sans-serif;
  width: 100%;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(165deg,#0c1220,#0a0f1a);
  padding: 44px 20px;
}

.btn-11__panel {
  width: min(520px,100%);
  background: #111827;
  border: 1px solid #1f2b40;
  border-radius: 20px;
  padding: 26px 24px 28px;
  box-shadow: 0 34px 80px -40px rgba(0,0,0,.9);
}

.btn-11__eyebrow {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--accent);
}

.btn-11__title {
  font-size: 23px;
  font-weight: 800;
  color: #eef3fb;
  letter-spacing: -.02em;
  margin: 5px 0 18px;
}

.btn-11__list {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.btn-11__in {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}

.btn-11__row {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 13px 15px;
  background: #0e1524;
  border: 1.5px solid #1e2a3f;
  border-radius: 14px;
  cursor: pointer;
  transition: border-color .18s,background .18s;
}

.btn-11__row:hover {
  border-color: #334563;
}

.btn-11__badge {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 800;
  color: #fff;
  background: var(--brand);
  box-shadow: 0 4px 14px -4px var(--brand);
