body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;box-sizing:border-box;font-family: 'Be Vietnam Pro', system-ui,sans-serif}
.cal23,
.cal23 *,
.cal23 *::before,
.cal23 *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.cal23 ::selection {
  background: #111;
  color: #fff;
}

.cal23 {
  --bg: #ececef;
  --card: #ffffff;
  --ink: #18181b;
  --ink2: #71717a;
  --ink3: #a1a1aa;
  --line: #e4e4e7;
  --accent: #4f46e5;
  --accent2: #06b6d4;
  --green: #10b981;
  --amber: #f59e0b;
  --rose: #f43f5e;
  font-family: 'Geist', -apple-system, sans-serif;
  background: var(--bg);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 32px 20px;
  color: var(--ink);
}

@keyframes cal23-in {
  from {
    opacity: 0;
    transform: translateY(14px) scale(0.99);
  }

  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes cal23-ring {
  to {
    stroke-dashoffset: var(--target);
  }
}

.cal23__wrap {
  max-width: 720px;
  width: 100%;
  animation: cal23-in 0.5s ease both;
}
/* ── Header ── */

.cal23__head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 16px;
  padding: 0 2px;
}

.cal23__title {
  font-size: 28px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.cal23__title span {
  color: var(--ink3);
  font-weight: 500;
}

.cal23__sub {
  font-size: 13px;
  color: var(--ink2);
  margin-top: 2px;
}

.cal23__nav {
  display: flex;
  gap: 6px;
}

.cal23__nav-btn {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  background: var(--card);
  border: 1px solid var(--line);
  cursor: pointer;
  color: var(--ink2);
  font-size: 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.18s;
  user-select: none;
}

.cal23__nav-btn:hover {
  border-color: var(--ink);
  color: var(--ink);
}
/* ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
   BENTO GRID — asymmetric spans.
   7 base columns; special cells span
   2×2 / 2×1 / 1×2 for the bento look.
   ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━ */

.cal23__bento {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  grid-auto-rows: 78px;
  gap: 8px;
}

.cal23__cell {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 12px;
  cursor: pointer;
  transition: all 0.18s;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

.cal23__cell:hover {
  border-color: var(--ink);
  transform: translateY(-2px);
  box-shadow: 0 8px 22px rgba(24,24,27,0.1);
}

.cal23__cell.other {
  background: transparent;
  border-color: transparent;
  pointer-events: none;
}

.cal23__cell.other .cal23__n {
  color: var(--ink3);
  opacity: 0.5;
}

.cal23__n {
  font-size: 16px;
  font-weight: 600;
  line-height: 1;
}

.cal23__cell .dow-mini {
  font-size: 10px;
  color: var(--ink3);
  font-weight: 500;
  margin-top: 2px;
}
/* span helpers */

.cal23__cell--2x2 {
  grid-column: span 2;
  grid-row: span 2;
}

.cal23__cell--2x1 {
  grid-column: span 2;
}

.cal23__cell--1x2 {
  grid-row: span 2;
}
/* ── TODAY: big 2×2 hero cell ── */

.cal23__cell--today {
  grid-column: span 2;
  grid-row: span 2;
  background: linear-gradient(135deg, var(--accent), #7c3aed);
  border-color: transparent;
  color: #fff;
  padding: 16px;
  justify-content: space-between;
}

.cal23__cell--today:hover {
  box-shadow: 0 14px 32px rgba(79,70,229,0.4);
}

.cal23__today-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.cal23__today-n {
  font-size: 40px;
  font-weight: 800;
  line-height: 0.9;
}

.cal23__today-badge {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: rgba(255,255,255,0.2);
  padding: 4px 9px;
  border-radius: 20px;
}

.cal23__today-label {
  font-size: 12px;
  opacity: 0.8;
}

.cal23__today-events {
  display: flex;
  gap: 5px;
  margin-top: 8px;
}

.cal23__today-ev {
  flex: 1;
  background: rgba(255,255,255,0.16);
  border-radius: 8px;
  padding: 6px 8px;
  font-size: 10px;
  font-weight: 500;
}
/* progress ring cell (an event with a goal) */

.cal23__ring-wrap {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 1;
}

.cal23__ring {
  transform: rotate(-90deg);
}

.cal23__ring-bg {
  fill: none;
  stroke: var(--line);
  stroke-width: 6;
}

.cal23__ring-fg {
  fill: none;
  stroke-width: 6;
  stroke-linecap: round;
  stroke-dasharray: 150.8;
  animation: cal23-ring 1.1s cubic-bezier(0.22,1,0.36,1) forwards;
}

.cal23__ring-label {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%,-50%);
  font-size: 13px;
  font-weight: 700;
}
/* event-rich 2x1 cell */

.cal23__cell--event {
  justify-content: space-between;
}

.cal23__cell--event .cal23__ev-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: auto;
}

.cal23__ev-icon {
  width: 24px;
  height: 24px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  flex-shrink: 0;
}

.cal23__ev-text {
  min-width: 0;
}

.cal23__ev-name {
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cal23__ev-time {
  font-size: 10px;
  color: var(--ink2);
}
/* selected */

.cal23__cell.selected {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}
/* mini event dots */

.cal23__dots {
  display: flex;
  gap: 3px;
  margin-top: auto;
}

.cal23__dots span {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}
/* corner pill for weekend */

.cal23__cell.weekend .cal23__n {
  color: var(--accent);
}

@media (max-width: 600px) {
  .cal23__bento {
    grid-auto-rows: 64px;
    gap: 6px;
  }

  .cal23__today-n {
    font-size: 30px;
  }

  .cal23__title {
    font-size: 22px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .cal23 * {
    animation: none !important;
    transition: none !important;
  }
}

body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;box-sizing:border-box;font-family: 'Be Vietnam Pro', system-ui,sans-serif}
.card-16 {
  width: 100%;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(28px, 5vw, 56px) clamp(20px, 4vw, 40px);
  box-sizing: border-box;
  background: radial-gradient(ellipse at 30% 20%, #1e293b 0%, transparent 60%), radial-gradient(ellipse at 80% 80%, #0f172a 0%, transparent 60%), #050815;
  font-family: 'Be Vietnam Pro', system-ui, sans-serif;
  --focus: #f5d97b;
  --gold: #d4b063;
  --gold-lite: #f5d97b;
}

.card-16 *,
.card-16 *::before,
.card-16 *::after {
  box-sizing: border-box;
}

.card-16__card {
  width: 360px;
  height: 220px;
  perspective: 1000px;
  border-radius: 14px;
}

.card-16__card:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 6px;
  border-radius: 14px;
}

.card-16__inner {
  position: relative;
  width: 100%;
  height: 100%;
  transform-style: preserve-3d;
  transition: transform 0.7s cubic-bezier(0.34, 1.2, 0.64, 1);
  box-shadow: 0 30px 60px -12px rgba(0, 0, 0, 0.6), 0 18px 36px -18px rgba(212, 176, 99, 0.35);
}

.card-16__card:hover .card-16__inner,
.card-16__card:focus-within .card-16__inner {
  transform: rotateY(180deg);
}

.card-16__face {
  position: absolute;
  inset: 0;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  border-radius: 14px;
  padding: 26px 28px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: linear-gradient(135deg, rgba(212, 176, 99, 0.14) 0%, transparent 40%, transparent 60%, rgba(212, 176, 99, 0.06) 100%), linear-gradient(160deg, #16213e 0%, #0f172a 50%, #050815 100%);
  border: 1px solid rgba(212, 176, 99, 0.28);
}

.card-16__face::before {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 60%;
  height: 60%;
  background: radial-gradient(circle at top right, rgba(245, 217, 123, 0.18), transparent 60%);
  pointer-events: none;
}

.card-16__front {
  justify-content: space-between;
}

.card-16__back {
  transform: rotateY(180deg);
  justify-content: space-between;
}

.card-16__brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.card-16__mark {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(135deg, #f5d97b 0%, #d4b063 50%, #9a7a3d 100%);
  box-shadow: inset 0 -2px 4px rgba(0, 0, 0, 0.25), inset 0 2px 4px rgba(255, 255, 255, 0.3), 0 2px 6px rgba(212, 176, 99, 0.35);
  position: relative;
}

.card-16__mark::before {
  content: '';
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  background: linear-gradient(135deg, #050815, #16213e);
}

.card-16__mark::after {
  content: 'A';
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 15px;
  font-weight: 700;
  color: #f5d97b;
  text-shadow: 0 1px 2px rgba(0,0,0,0.6);
}

.card-16__brandname {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.24em;
  color: var(--gold);
  text-transform: uppercase;
}

.card-16__id {
  margin-bottom: 12px;
}

.card-16__name {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 26px;
  font-weight: 700;
  margin: 0 0 4px;
  color: #f8fafc;
  letter-spacing: -0.005em;
  line-height: 1.1;
}

.card-16__role {
  font-size: 11px;
  font-weight: 500;
  color: rgba(245, 217, 123, 0.85);
  margin: 0;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.card-16__hint {
  align-self: flex-end;
  font-size: 9.5px;
  color: rgba(148, 163, 184, 0.6);
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.card-16__backbrand {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.28em;
  color: rgba(212, 176, 99, 0.75);
  text-transform: uppercase;
}

.card-16__contact {
  font-style: normal;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.card-16__row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 44px;
  padding-top: 4px;
  padding-bottom: 4px;
  border-bottom: 1px solid rgba(212, 176, 99, 0.14);
}

.card-16__row:last-child {
  border-bottom: 0;
}

.card-16__ico {
  color: var(--gold);
  flex-shrink: 0;
}

.card-16__row a {
  color: #e2e8f0;
  text-decoration: none;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.01em;
  transition: color 0.18s;
}

.card-16__row a:hover {
  color: var(--gold-lite);
}

.card-16__row a:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .card-16__inner {
    transition: none;
  }

  .card-16__card:hover .card-16__inner,
    .card-16__card:focus-within .card-16__inner {
    transform: none;
  }
}

