@import url('https://fonts.googleapis.com/css2?family=Sora:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap');

.fu-05 {
  --bg: #fbfbfd;
  --surface: #ffffff;
  --ink: #0a0a0f;
  --muted: #4d5361;
  --line: #d8dce5;
  --acc: #1740ff;
  --ok: #0a7d4f;
  --danger: #c81e35;
  --ring: #1740ff;
  --sans: "Sora",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
  --mono: "IBM Plex Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
  width: 100%;
  min-height: 100vh;
  min-height: 100svh;
  display: grid;
  place-items: center;
  padding: clamp(1.25rem,5vw,4rem);
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
}

.fu-05,
.fu-05 *,
.fu-05 *::before,
.fu-05 *::after {
  box-sizing: border-box;
}

@supports (color: oklch(0 0 0)) {
  .fu-05 {
    --acc: oklch(48% .26 268);
    --ok: oklch(50% .13 158);
    --danger: oklch(52% .21 22);
  }
}

.fu-05__card {
  inline-size: min(31rem,100%);
  display: grid;
  gap: 1rem;
  /* grid items default to min-width:auto, so a long unbroken filename in
       the status row would otherwise force the card past its own width */
  grid-template-columns: minmax(0,1fr);
  padding: clamp(1.25rem,4vw,2rem);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 1.25rem;
  box-shadow: 0 20px 45px -35px rgba(10,10,15,.4);
}

.fu-05__h {
  margin: 0;
  font-size: clamp(1.25rem,3vw,1.5rem);
  font-weight: 600;
  letter-spacing: -.025em;
  text-wrap: balance;
}

.fu-05__field {
  position: relative;
}

.fu-05__input {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  margin: 0;
  border: 0;
  overflow: hidden;
  opacity: 0;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
}

.fu-05__label {
  display: flex;
  align-items: center;
  gap: 1rem;
  cursor: pointer;
  user-select: none;
  min-block-size: 4.5rem;
  padding: 1rem 1.15rem;
  border-radius: 1rem;
  border: 2px solid var(--line);
  background: var(--surface);
  transition: border-color .25s ease, background .25s ease, box-shadow .25s ease;
}

.fu-05__label:hover {
  border-color: var(--acc);
  background: color-mix(in oklab,var(--acc) 5%,var(--surface));
}

.fu-05__input:focus-visible + .fu-05__label {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
  border-color: var(--acc);
}

.fu-05__icon {
  display: grid;
  place-items: center;
  inline-size: 2.75rem;
  block-size: 2.75rem;
  flex: none;
  border-radius: .8rem;
  background: color-mix(in oklab,var(--acc) 12%,transparent);
  color: var(--acc);
}

.fu-05__icon svg {
  inline-size: 1.35rem;
  block-size: 1.35rem;
}

.fu-05__labelCol {
  display: grid;
  gap: .2rem;
}

.fu-05__labelTop {
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: -.015em;
}

.fu-05__labelSub {
  font-family: var(--mono);
  font-size: .75rem;
  color: var(--muted);
}
/* error state derives from the same attribute assistive tech reads */

.fu-05__field:has(.fu-05__input[aria-invalid="true"]) .fu-05__label {
  border-color: var(--danger);
  background: color-mix(in oklab,var(--danger) 7%,var(--surface));
}

.fu-05__field:has(.fu-05__input[aria-invalid="true"]) .fu-05__icon {
  background: color-mix(in oklab,var(--danger) 14%,transparent);
  color: var(--danger);
}

.fu-05__err {
  margin: 0;
  display: flex;
  gap: .5rem;
  padding: .7rem .85rem;
  border-radius: .75rem;
  background: color-mix(in oklab,var(--danger) 10%,transparent);
  border: 1px solid color-mix(in oklab,var(--danger) 35%,transparent);
  color: color-mix(in oklab,var(--danger) 75%,var(--ink));
  font-size: .875rem;
  line-height: 1.5;
}

.fu-05__err[hidden] {
  display: none;
}

.fu-05__err::before {
  content: "!";
  font-weight: 700;
  font-family: var(--mono);
}

.fu-05__ok {
  display: flex;
  align-items: center;
  gap: .7rem;
  min-inline-size: 0;
  padding: .7rem .85rem;
  border-radius: .75rem;
  background: color-mix(in oklab,var(--ok) 9%,transparent);
  border: 1px solid color-mix(in oklab,var(--ok) 32%,transparent);
  color: color-mix(in oklab,var(--ok) 78%,var(--ink));
  font-size: .875rem;
}

.fu-05__ok[hidden] {
  display: none;
}

.fu-05__ok svg {
  inline-size: 1.15rem;
  block-size: 1.15rem;
  flex: none;
}

.fu-05__okName {
  flex: 1;
  min-inline-size: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 600;
}

.fu-05__undo {
  min-block-size: 2.75rem;
  padding: .5rem .9rem;
  cursor: pointer;
  border-radius: .6rem;
  border: 1px solid color-mix(in oklab,var(--ok) 40%,transparent);
