  color: inherit;
  font-family: var(--sans);
  font-size: .8125rem;
  font-weight: 600;
  transition: background .2s ease;
}

.fu-05__undo:hover {
  background: color-mix(in oklab,var(--ok) 14%,transparent);
}

.fu-05__undo:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

.fu-05__status {
  margin: 0;
  min-block-size: 1rem;
  font-family: var(--mono);
  font-size: .75rem;
  color: var(--muted);
}

@media (prefers-color-scheme: dark) {
  .fu-05:not([data-theme="light"]) {
    --bg: #08080c;
    --surface: #101118;
    --ink: #f4f5f9;
    --muted: #98a0b2;
    --line: #272c3a;
    --acc: #8aa0ff;
    --ok: #4ade9b;
    --danger: #ff7a8a;
    --ring: #8aa0ff;
  }
}

.fu-05[data-theme="dark"] {
  --bg: #08080c;
  --surface: #101118;
  --ink: #f4f5f9;
  --muted: #98a0b2;
  --line: #272c3a;
  --acc: #8aa0ff;
  --ok: #4ade9b;
  --danger: #ff7a8a;
  --ring: #8aa0ff;
}

