  clip-path: circle(150% at 50% 50%);
  -webkit-clip-path: circle(150% at 50% 50%);
  z-index: 1;
}

.fc-21__back {
  background: linear-gradient(160deg,#0a0612 0%,#1e0b3b 100%);
  clip-path: circle(0% at 50% 50%);
  -webkit-clip-path: circle(0% at 50% 50%);
  z-index: 2;
}

.fc-21__scene:hover .fc-21__front {
  clip-path: circle(0% at 50% 50%);
  -webkit-clip-path: circle(0% at 50% 50%);
}

.fc-21__scene:hover .fc-21__back {
  clip-path: circle(150% at 50% 50%);
  -webkit-clip-path: circle(150% at 50% 50%);
}
/* FRONT — album cover */

.fc-21__cover {
  margin-top: 6px;
  border-radius: 4px;
  overflow: hidden;
  box-shadow: 0 14px 30px rgba(0,0,0,.5);
}

.fc-21__cover-meta {
  margin-top: 22px;
  text-align: center;
  width: 100%;
}

.fc-21__artist {
  font-size: 11px;
  letter-spacing: .45em;
  color: var(--neon);
  font-weight: 700;
}

.fc-21__album {
  font-size: 23px;
  font-weight: 800;
  color: var(--ink);
  margin-top: 6px;
  letter-spacing: -.02em;
  font-family: 'Playfair Display',Georgia,serif;
  font-style: italic;
}

.fc-21__pill-row {
  display: flex;
  justify-content: center;
  gap: 6px;
  margin-top: 12px;
}

.fc-21__pill {
  padding: 4px 11px;
  border: 1px solid rgba(236,72,153,.4);
  border-radius: 999px;
  font-size: 9px;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: rgba(245,232,255,.7);
  font-weight: 600;
}

.fc-21__hint {
  margin-top: auto;
  font-size: 10px;
  letter-spacing: .2em;
  text-transform: uppercase;
  color: rgba(245,232,255,.4);
}
/* BACK — tracklist */

.fc-21__back-head {
  display: flex;
  justify-content: space-between;
  width: 100%;
  padding-bottom: 14px;
  margin-bottom: 14px;
  border-bottom: 1px solid rgba(236,72,153,.25);
  font-size: 10px;
  letter-spacing: .3em;
  text-transform: uppercase;
  color: var(--neon);
  font-weight: 700;
}

.fc-21__back-runtime {
  color: rgba(245,232,255,.55);
  font-family: ui-monospace,monospace;
  letter-spacing: .1em;
}

.fc-21__tracklist {
  display: flex;
  flex-direction: column;
  gap: 1px;
  width: 100%;
  flex: 1;
}

.fc-21__track {
  display: grid;
  grid-template-columns: 28px 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 10px 8px;
  border-radius: 6px;
  transition: background .15s;
  cursor: pointer;
}

.fc-21__track:hover {
  background: rgba(236,72,153,.08);
}

.fc-21__t-num {
  font-family: ui-monospace,monospace;
  font-size: 10px;
  color: rgba(245,232,255,.4);
  letter-spacing: .1em;
}

.fc-21__t-name {
  font-size: 13px;
  color: var(--ink);
  font-weight: 500;
}

.fc-21__t-time {
  font-family: ui-monospace,monospace;
  font-size: 11px;
  color: rgba(245,232,255,.4);
  letter-spacing: .05em;
}

.fc-21__play {
  margin-top: 14px;
  width: 100%;
  padding: 13px 0;
  border: 1px solid rgba(236,72,153,.5);
  border-radius: 8px;
  background: linear-gradient(135deg,rgba(236,72,153,.18),rgba(162,28,175,.12));
  color: var(--neon);
  font-size: 12px;
  letter-spacing: .25em;
  text-transform: uppercase;
  font-weight: 700;
  cursor: pointer;
  transition: background .2s,box-shadow .2s;
  font-family: inherit;
}

.fc-21__play:hover {
  background: linear-gradient(135deg,rgba(236,72,153,.3),rgba(162,28,175,.2));
  box-shadow: 0 8px 24px rgba(236,72,153,.25);
}

@media (prefers-reduced-motion: reduce) {
  .fc-21__front,
    .fc-21__back {
    transition: none;
  }
}

body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;box-sizing:border-box;font-family: 'Be Vietnam Pro', system-ui,sans-serif}
.fb-05 {
  width: 100%;
  min-height: 100vh;
  min-height: 100svh;
  display: block;
  background: var(--fb-05-bg);
  --fb-05-bg: oklch(0.98 0.008 250);
  --fb-05-brand: oklch(0.48 0.19 262);
  --fb-05-brandDeep: oklch(0.38 0.17 262);
  --fb-05-ink: oklch(0.21 0.02 260);
  --fb-05-mut: oklch(0.5 0.02 260);
  --fb-05-card: oklch(1 0 0);
  font-family: 'Segoe UI',system-ui,-apple-system,sans-serif;
  color: var(--fb-05-ink);
  position: relative;
  display: grid;
  place-items: center;
  padding: clamp(20px,5vw,56px);
  overflow: hidden;
}

.fb-05 *,
.fb-05 *::before,
.fb-05 *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.fb-05__page {
  width: min(100%,58ch);
  display: grid;
  gap: 13px;
  justify-items: center;
  text-align: center;
  z-index: 1;
}

.fb-05__eyebrow {
  font-family: ui-monospace,Menlo,Consolas,monospace;
  font-size: 11.5px;
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--fb-05-brand);
}

.fb-05__title {
  font-size: clamp(26px,4.6vw,44px);
  line-height: 1.05;
  letter-spacing: -.03em;
  font-weight: 700;
  text-wrap: balance;
}

.fb-05__sub {
  font-size: clamp(13.5px,1.7vw,16.5px);
  line-height: 1.62;
  color: var(--fb-05-mut);
  text-wrap: pretty;
}

.fb-05__keys {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  font-size: 12px;
  color: var(--fb-05-mut);
}

.fb-05__keys li {
  display: flex;
  align-items: center;
  gap: 5px;
  background: var(--fb-05-card);
  border: 1px solid oklch(0.21 0.02 260/.12);
  border-radius: 99px;
  padding: 6px 12px;
}

.fb-05 kbd {
  font-family: ui-monospace,Menlo,Consolas,monospace;
  font-size: 11px;
  background: oklch(0.94 0.008 260);
  border: 1px solid oklch(0.21 0.02 260/.16);
  border-bottom-width: 2px;
  border-radius: 5px;
  padding: 1px 5px;
  color: var(--fb-05-ink);
}

.fb-05__live {
  font-family: ui-monospace,Menlo,Consolas,monospace;
  font-size: 12px;
  color: var(--fb-05-brandDeep);
  background: oklch(0.48 0.19 262/.08);
  border: 1px dashed oklch(0.48 0.19 262/.35);
  border-radius: 12px;
  padding: 9px 15px;
  min-height: 36px;
  display: grid;
  place-items: center;
}

.fb-05__scrim {
  position: absolute;
  inset: 0;
  z-index: 4;
  background: oklch(0.21 0.02 260/.42);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
  animation: fb-05-fade .2s ease;
}

.fb-05__scrim[hidden] {
  display: none;
}

@keyframes fb-05-fade {
  from {
    opacity: 0;
  }
}

.fb-05__dock {
  position: absolute;
  right: clamp(16px,3vw,32px);
  bottom: calc(clamp(16px,3vw,32px) + env(safe-area-inset-bottom));
  z-index: 5;
  display: grid;
  justify-items: end;
  gap: 14px;
}

.fb-05__menu {
  list-style: none;
  display: grid;
  gap: 9px;
  justify-items: end;
}

.fb-05__menu[hidden] {
  display: none;
}

.fb-05__item {
  display: flex;
  align-items: center;
  gap: 11px;
  min-height: 48px;
  padding: 0 18px 0 10px;
  border: 1px solid oklch(0.21 0.02 260/.1);
  border-radius: 99px;
  background: var(--fb-05-card);
  color: var(--fb-05-ink);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  box-shadow: 0 10px 26px -14px oklch(0.21 0.02 260/.7);
  animation: fb-05-rise .26s cubic-bezier(.2,.9,.3,1.1) backwards;
  transition: transform .18s ease,background .18s ease;
}

.fb-05__menu li:nth-child(1) .fb-05__item {
  animation-delay: .02s;
}

.fb-05__menu li:nth-child(2) .fb-05__item {
  animation-delay: .06s;
}

.fb-05__menu li:nth-child(3) .fb-05__item {
  animation-delay: .1s;
}

.fb-05__menu li:nth-child(4) .fb-05__item {
  animation-delay: .14s;
}

@keyframes fb-05-rise {
  from {
    opacity: 0;
    transform: translateY(14px) scale(.94);
  }
}

.fb-05__item:hover {
  background: oklch(0.96 0.01 262);
  transform: translateX(-2px);
}

.fb-05__item:focus-visible,
.fb-05__fab:focus-visible {
  outline: 3px solid var(--fb-05-brandDeep);
  outline-offset: 3px;
  box-shadow: 0 0 0 6px oklch(1 0 0/.9),0 10px 26px -14px oklch(0.21 0.02 260/.7);
}

.fb-05__iBox {
  flex: none;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: oklch(0.48 0.19 262/.1);
  color: var(--fb-05-brandDeep);
}

.fb-05__iBox svg {
  width: 20px;
  height: 20px;
}

.fb-05__fab {
  display: grid;
  place-items: center;
  inline-size: 60px;
  block-size: 60px;
  border: 0;
  border-radius: 20px;
  cursor: pointer;
  color: oklch(0.99 0.01 262);
  background: linear-gradient(150deg,oklch(0.56 0.2 268),var(--fb-05-brandDeep));
  box-shadow: 0 12px 30px -10px oklch(0.38 0.17 262/.8),0 2px 6px oklch(0.3 0.1 262/.28);
  transition: transform .28s cubic-bezier(.2,1.3,.4,1),border-radius .28s ease;
}

.fb-05__fab svg {
  width: 26px;
  height: 26px;
  transition: rotate .3s cubic-bezier(.3,1.4,.4,1);
}

.fb-05__fab:hover {
  transform: translateY(-2px);
}

.fb-05__fab:active {
  transform: scale(.94);
}

.fb-05__fab[aria-expanded="true"] {
  border-radius: 50%;
}

.fb-05__fab[aria-expanded="true"] svg {
  rotate: 135deg;
}

@media (forced-colors: active) {
  .fb-05__item,
    .fb-05__fab {
    border: 1px solid ButtonText;
  }
}

@media (prefers-reduced-motion: reduce) {
  .fb-05 * {
    animation: none !important;
    transition: none !important;
  }
}

body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;box-sizing:border-box;font-family: 'Be Vietnam Pro', system-ui,sans-serif}
.flb-07,
.flb-07 *,
.flb-07 *::before,
.flb-07 *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.flb-07 {
  --accent: oklch(0.5 0.19 264);
  font-family: 'Segoe UI',system-ui,sans-serif;
  width: 100%;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #eef0f4;
  padding: 40px 20px;
}

.flb-07__form {
  width: min(400px,100%);
  background: #fff;
  border-radius: 18px;
  padding: 32px 30px;
  box-shadow: 0 20px 50px -28px rgba(24,28,60,.3);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.flb-07__title {
  font-size: 23px;
  font-weight: 800;
  color: #171a26;
  letter-spacing: -.02em;
  margin-bottom: 14px;
}

.flb-07__field {
  position: relative;
  padding-bottom: 30px;
}

.flb-07__input {
  width: 100%;
  height: 58px;
  padding: 24px 16px 6px;
  font-size: 16px;
  color: #171a26;
  background: #fff;
  border: 2px solid #c2c7d4;
  border-radius: 10px;
  outline: none;
  transition: border-color .2s;
}

.flb-07__input:hover {
  border-color: #9aa0b2;
}

.flb-07__input:focus {
  border-color: var(--accent);
}

.flb-07__input:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.flb-07__label {
  position: absolute;
  left: 16px;
  top: 29px;
  translate: 0 -50%;
  font-size: 16px;
  color: #5a5f6e;
  pointer-events: none;
  transform-origin: left center;
  transition: transform .18s,color .18s;
}

.flb-07__input:focus ~ .flb-07__label,
.flb-07__input:not(:placeholder-shown) ~ .flb-07__label {
  transform: translateY(-15px) scale(.85);
  font-weight: 700;
}

.flb-07__label::before {
  content: "";
  display: inline-block;
  width: 0;
  height: 3px;
  border-radius: 2px;
  background: var(--accent);
  vertical-align: middle;
  transition: width .2s,margin-right .2s;
}

.flb-07__input:focus ~ .flb-07__label::before,
.flb-07__input:not(:placeholder-shown) ~ .flb-07__label::before {
  width: 12px;
  margin-right: 6px;
}

.flb-07__input:focus ~ .flb-07__label {
  color: var(--accent);
}

.flb-07__req {
  color: oklch(0.5 0.19 25);
  font-weight: 700;
}

.flb-07__hint {
  position: absolute;
  left: 2px;
  bottom: 6px;
  font-size: 12.5px;
  color: #5a5f6e;
  line-height: 1.35;
}

.flb-07__btn {
  height: 52px;
  border: none;
  border-radius: 10px;
  background: var(--accent);
  color: #fff;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  transition: filter .15s;
}

.flb-07__btn:hover {
  filter: brightness(1.12);
}

.flb-07__btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .flb-07__label,
    .flb-07__input {
    transition: none;
  }
}

body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;box-sizing:border-box;font-family: 'Be Vietnam Pro', system-ui,sans-serif}
.fv-11 {
  --page: #ffffff;
  --surface: #ffffff;
  --panel: #f4f7fa;
  --ink: #0f1a24;
  --muted: #4e6070;
  --rule: #dfe6ec;
  --accent: #0b6ea8;
  --error: #b8264f;
  --error-ink: #971d40;
  --gap: 2rem;
  --font-display: "Seravek", "Gill Sans Nova", Optima, "Segoe UI", system-ui, sans-serif;
  width: 100%;
  min-height: 100vh;
  display: block;
  box-sizing: border-box;
  background: var(--page);
  color: var(--ink);
  font-family: system-ui, sans-serif;
}

@supports (color: oklch(0 0 0)) {
  .fv-11 {
    --accent: oklch(0.5 0.13 240);
    --error: oklch(0.47 0.17 5);
    --error-ink: oklch(0.4 0.17 5);
  }
}

.fv-11 *,
.fv-11 *::before,
.fv-11 *::after {
  box-sizing: border-box;
}

.fv-11 [hidden] {
  display: none;
}

.fv-11__stage {
  display: grid;
  place-items: start center;
  max-inline-size: 100%;
  padding: clamp(1.5rem, 5vw, 4rem) clamp(1rem, 4vw, 3rem);
}

.fv-11__head {
  inline-size: min(100%, 58rem);
  min-inline-size: 0;
  padding-block-end: 1.5rem;
  border-block-end: 1px solid var(--rule);
  margin-block-end: var(--gap);
}

.fv-11__eyebrow {
  margin: 0 0 0.625rem;
  font-size: 0.6875rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent);
}

.fv-11__h {
  margin: 0 0 0.5rem;
  font-family: var(--font-display);
  font-size: clamp(1.4rem, 4vw, 2.2rem);
  font-weight: 600;
  line-height: 1.12;
  letter-spacing: -0.015em;
  text-wrap: balance;
}

.fv-11__sub {
  margin: 0;
  max-inline-size: 38rem;
  font-size: 0.9375rem;
  line-height: 1.6;
  color: var(--muted);
}

.fv-11__split {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 19rem), 1fr));
  gap: var(--gap);
  inline-size: min(100%, 58rem);
}

.fv-11__form {
  display: grid;
  gap: var(--gap);
  align-content: start;
  min-inline-size: 0;
}

.fv-11__field {
  display: grid;
  gap: 0.5rem;
  min-inline-size: 0;
  padding-block-end: var(--gap);
  border-block-end: 1px solid var(--rule);
}

.fv-11__field:last-of-type {
  border-block-end: 0;
  padding-block-end: 0;
}

.fv-11__label {
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.005em;
}

.fv-11__input {
  min-inline-size: 0;
  inline-size: 100%;
  block-size: 3rem;
  padding: 0 0.875rem;
  font: inherit;
  font-size: 1rem;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--rule);
  border-radius: 0.25rem;
}

.fv-11__input::placeholder {
  color: #93a3b0;
}

.fv-11__input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.fv-11__input:invalid:not(:placeholder-shown):not(:focus) {
  border-color: var(--error);
  border-inline-start-width: 4px;
}

.fv-11__input:user-invalid {
  border-color: var(--error);
  border-inline-start-width: 4px;
}

.fv-11__input[aria-invalid="true"] {
  border-color: var(--error);
  border-inline-start-width: 4px;
}

.fv-11__msg {
  display: flex;
  gap: 0.4375rem;
  align-items: flex-start;
  margin: 0;
  min-inline-size: 0;
  font-size: 0.875rem;
  line-height: 1.45;
  color: var(--error-ink);
}

.fv-11__msg span {
  min-inline-size: 0;
}

.fv-11__icon {
  flex: none;
  inline-size: 1.0625rem;
  block-size: 1.0625rem;
  margin-block-start: 0.1rem;
}

.fv-11__btn {
  justify-self: start;
  min-block-size: 2.875rem;
  min-inline-size: 44px;
  padding: 0.75rem 1.375rem;
  font: inherit;
  font-size: 0.9375rem;
  font-weight: 600;
  color: #ffffff;
  background: var(--accent);
  border: 0;
  border-radius: 0.25rem;
  cursor: pointer;
}

.fv-11__btn:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 3px;
}

.fv-11__inspect {
  min-inline-size: 0;
  align-self: start;
  padding: 1.25rem;
  background: var(--panel);
  border: 1px solid var(--rule);
  border-radius: 0.25rem;
}

.fv-11__insphead {
  margin: 0 0 0.875rem;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 600;
}

.fv-11__rows {
  margin: 0;
  display: grid;
  gap: 0;
}

.fv-11__row {
  display: grid;
  grid-template-columns: minmax(0, 8rem) minmax(0, 1fr);
  gap: 0.5rem;
  padding-block: 0.5rem;
  border-block-end: 1px solid var(--rule);
}

.fv-11__row:last-child {
  border-block-end: 0;
}

.fv-11__row dt {
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted);
  min-inline-size: 0;
}

.fv-11__row dd {
  margin: 0;
  min-inline-size: 0;
  font-size: 0.8125rem;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.fv-11__row dd[data-slot="state"] {
  font-weight: 600;
}

.fv-11__inspnote {
  margin: 0.875rem 0 0;
  font-size: 0.75rem;
  line-height: 1.5;
  color: var(--muted);
}

@media (prefers-color-scheme: dark) {
  .fv-11:not(:has(#fv-11-theme-light:checked)) {
    --page: #070e14;
    --surface: #0d161e;
    --panel: #101b25;
    --ink: #e7eff5;
    --muted: #93a6b6;
    --rule: #1d2b37;
    --accent: #4aa8e0;
    --error: #ff6f92;
    --error-ink: #ff92ab;
  }

  .fv-11:not(:has(#fv-11-theme-light:checked)) .fv-11__input::placeholder {
    color: #64798a;
  }

  .fv-11:not(:has(#fv-11-theme-light:checked)) .fv-11__btn {
    color: #04121c;
  }
}

[data-theme="dark"] .fv-11:not(:has(#fv-11-theme-light:checked)) {
  --page: #070e14;
  --surface: #0d161e;
  --panel: #101b25;
  --ink: #e7eff5;
  --muted: #93a6b6;
  --rule: #1d2b37;
  --accent: #4aa8e0;
  --error: #ff6f92;
  --error-ink: #ff92ab;
}

[data-theme="dark"] .fv-11:not(:has(#fv-11-theme-light:checked)) .fv-11__btn {
  color: #04121c;
}

.fv-11 {
  position: relative;
}

.fv-11__stage {
  padding-block-start: 4.75rem;
}

.fv-11__theme {
  position: absolute;
  inset-block-start: 0.875rem;
  inset-inline-end: 0.875rem;
  z-index: 6;
  display: flex;
  align-items: center;
  gap: 0.125rem;
  margin: 0;
  padding: 0.1875rem;
  border: 1px solid color-mix(in srgb, currentColor 18%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, currentColor 7%, transparent);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  font-family: system-ui, sans-serif;
}

.fv-11__themelegend {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
}

.fv-11__themeinput {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  margin: 0;
  overflow: hidden;
  clip-path: inset(50%);
}

.fv-11__themeopt {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-block-size: 1.875rem;
  padding: 0 0.6875rem;
  border-radius: 999px;
  font-size: 0.6875rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: inherit;
  opacity: 0.55;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
}

.fv-11__themeopt:hover {
  opacity: 0.85;
}

.fv-11__themeinput:checked + .fv-11__themeopt {
  opacity: 1;
  background: color-mix(in srgb, currentColor 15%, transparent);
}

.fv-11__themeinput:focus-visible + .fv-11__themeopt {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

@media (forced-colors: active) {
  .fv-11__theme {
    border-color: CanvasText;
    background: Canvas;
  }

  .fv-11__themeinput:checked + .fv-11__themeopt {
    background: Highlight;
    color: HighlightText;
  }
}

.fv-11:has(#fv-11-theme-dark:checked) {
  --page: #070e14;
  --surface: #0d161e;
  --panel: #101b25;
  --ink: #e7eff5;
  --muted: #93a6b6;
  --rule: #1d2b37;
  --accent: #4aa8e0;
  --error: #ff6f92;
  --error-ink: #ff92ab;
}

.fv-11:has(#fv-11-theme-dark:checked) .fv-11__input::placeholder {
  color: #64798a;
}

.fv-11:has(#fv-11-theme-dark:checked) .fv-11__btn {
  color: #04121c;
}

body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;box-sizing:border-box;font-family: 'Be Vietnam Pro', system-ui,sans-serif}
@import url('https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700&family=JetBrains+Mono:wght@500&display=swap');

.frm-03 {
  --bg: #eef1f5;
  --surface: #ffffff;
  --sum: #f7f8fb;
  --ink: #0f172a;
  --muted: #64748b;
  --line: #e2e8f0;
  --accent: #4f46e5;
  --on-accent: #fff;
  --ok: #059669;
  --bad: #dc2626;
  --card-a: #1e293b;
  --card-b: #475569;
  --sans: "Figtree",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
  --mono: "JetBrains Mono",ui-monospace,Menlo,monospace;
  --ease: cubic-bezier(.16,1,.3,1);
  width: 100%;
  min-height: 100vh;
  min-height: 100svh;
  display: block;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
}

@media (prefers-color-scheme: dark) {
  .frm-03:not([data-theme="light"]) {
    --bg: #0b0f17;
    --surface: #121826;
    --sum: #0f1520;
    --ink: #e7ecf5;
    --muted: #8a96ab;
    --line: #232c3d;
    --accent: #818cf8;
    --on-accent: #0b0d24;
    --ok: #34d399;
    --bad: #f87171;
  }
}

.frm-03[data-theme="dark"] {
  --bg: #0b0f17;
  --surface: #121826;
  --sum: #0f1520;
  --ink: #e7ecf5;
  --muted: #8a96ab;
  --line: #232c3d;
  --accent: #818cf8;
  --on-accent: #0b0d24;
  --ok: #34d399;
  --bad: #f87171;
}

.frm-03[data-brand="visa"] {
  --card-a: #1a1f71;
  --card-b: #3b5bdb;
}

.frm-03[data-brand="mastercard"] {
  --card-a: #2b1b10;
  --card-b: #c2410c;
}

.frm-03[data-brand="amex"] {
  --card-a: #0b4f6c;
  --card-b: #14b8a6;
}

.frm-03,
.frm-03 *,
.frm-03 *::before,
.frm-03 *::after {
  box-sizing: border-box;
}

.frm-03__stage {
  min-height: 100vh;
  min-height: 100svh;
  display: grid;
  place-items: center;
  padding: clamp(1rem,4vw,3.5rem);
}

.frm-03__wrap {
  container-type: inline-size;
  width: 100%;
  max-width: 68rem;
}

.frm-03__grid {
  display: grid;
  grid-template-columns: 1fr;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 1.5rem;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(15,23,42,.04), 0 30px 70px -35px rgba(15,23,42,.35);
}

@container (min-width: 52rem) {
  .frm-03__grid {
    grid-template-columns: minmax(0,1.25fr) minmax(0,1fr);
  }
}

.frm-03__pay {
  display: grid;
  gap: 1.1rem;
  align-content: start;
  padding: clamp(1.25rem,4cqi,2.75rem);
}

.frm-03__summary {
  display: grid;
  gap: 1rem;
  align-content: start;
  padding: clamp(1.25rem,4cqi,2.75rem);
  background: var(--sum);
  border-top: 1px solid var(--line);
}

@container (min-width: 52rem) {
  .frm-03__summary {
    border-top: 0;
    border-left: 1px solid var(--line);
  }
}

@container (max-width: 51.99rem) {
  .frm-03__summary {
    order: -1;
    border-top: 0;
    border-bottom: 1px solid var(--line);
  }
}

.frm-03__steps {
  display: flex;
  gap: .5rem;
  font-size: .8rem;
  color: var(--muted);
}

.frm-03__steps span {
  display: flex;
  align-items: center;
  gap: .5rem;
}

.frm-03__steps span:not(:last-child)::after {
  content: '';
  width: 1.25rem;
  height: 1px;
  background: var(--line);
}

.frm-03__steps [aria-current] {
  color: var(--ink);
  font-weight: 600;
}

.frm-03 h2 {
  margin: 0;
  font-size: 1.75rem;
  letter-spacing: -.03em;
}

.frm-03 h3 {
  margin: 0;
  font-size: 1.1rem;
  letter-spacing: -.01em;
}

.frm-03__methods {
  border: 0;
  margin: 0;
  padding: .3rem;
  display: grid;
  grid-template-columns: repeat(3,1fr);
  gap: .3rem;
  background: var(--sum);
  border-radius: 1rem;
  border: 1px solid var(--line);
}

.frm-03__methods label {
  position: relative;
}

.frm-03__methods input {
  position: absolute;
  inset: 0;
  opacity: 0;
  margin: 0;
  cursor: pointer;
}

.frm-03__methods span {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  min-height: 2.75rem;
  border-radius: .75rem;
  font-size: .9rem;
  font-weight: 600;
  color: var(--muted);
  transition: background .25s, color .25s, box-shadow .25s;
}

.frm-03__methods svg {
  width: 1.15rem;
  height: 1.15rem;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.frm-03__methods input:checked + span {
  background: var(--surface);
  color: var(--ink);
  box-shadow: 0 1px 2px rgba(0,0,0,.06), 0 4px 12px -4px rgba(0,0,0,.12);
}

.frm-03__methods input:focus-visible + span {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.frm-03__panel {
  display: none;
  gap: 1rem;
}

.frm-03__panel p {
  margin: 0;
  padding: 1rem 1.1rem;
  border-radius: 1rem;
  background: var(--sum);
  border: 1px dashed var(--line);
  color: var(--muted);
  line-height: 1.55;
}

.frm-03:has([value="card"]:checked) .frm-03__panel--card,
.frm-03:has([value="wallet"]:checked) .frm-03__panel--wallet,
.frm-03:has([value="bank"]:checked) .frm-03__panel--bank {
  display: grid;
  animation: frm-03-in .45s var(--ease);
}

@keyframes frm-03-in {
  from {
    opacity: 0;
    translate: 0 8px;
  }
}

.frm-03__card3d {
  position: relative;
  width: min(100%,21rem);
  aspect-ratio: 1.586;
  margin: .25rem auto .5rem;
  transform-style: preserve-3d;
  transition: rotate .8s var(--ease);
  perspective: 1000px;
}

.frm-03:has(#frm-03-cvc:focus) .frm-03__card3d {
  rotate: y 180deg;
}

.frm-03__face {
  position: absolute;
  inset: 0;
  border-radius: 1rem;
  padding: 1.15rem 1.25rem;
  color: #fff;
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  background: radial-gradient(120% 140% at 0% 0%, color-mix(in oklab,var(--card-b) 90%,white), transparent 55%), linear-gradient(135deg,var(--card-a),var(--card-b));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.25), 0 24px 40px -18px color-mix(in oklab,var(--card-a) 80%,black);
  transition: background .5s;
}

.frm-03__face--front {
  display: grid;
  grid-template-rows: auto 1fr auto;
}

.frm-03__face--front::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(115deg,transparent 30%,rgba(255,255,255,.18) 45%,transparent 60%);
  pointer-events: none;
}

.frm-03__face--back {
  rotate: y 180deg;
  display: grid;
  align-content: center;
  gap: .8rem;
  padding: 1.15rem 0;
}

.frm-03__face--back i {
  height: 2.4rem;
  background: #0a0a0a;
}

.frm-03__pcvc {
  justify-self: end;
  margin-right: 1.25rem;
  padding: .35rem .7rem;
  background: #f8fafc;
  color: #0f172a;
  border-radius: .35rem;
  font: 500 .95rem var(--mono);
  letter-spacing: .15em;
}

.frm-03__chiprow {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.frm-03__chip {
  width: 2.4rem;
  height: 1.75rem;
  border-radius: .35rem;
  background: linear-gradient(135deg,#f5d77a,#b8913a);
  box-shadow: inset 0 0 0 1px rgba(0,0,0,.2);
}

.frm-03__brand {
  font-weight: 700;
  font-size: 1rem;
  letter-spacing: .04em;
  font-style: italic;
}

.frm-03__pnum {
  align-self: center;
  font: 500 clamp(1rem,4.6cqi,1.3rem) var(--mono);
  letter-spacing: .08em;
  text-shadow: 0 1px 1px rgba(0,0,0,.3);
  white-space: nowrap;
}

.frm-03__prow {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
}

.frm-03__prow span {
  display: grid;
  gap: .1rem;
  min-width: 0;
}

.frm-03__prow small {
  font-size: .6rem;
  text-transform: uppercase;
  letter-spacing: .12em;
  opacity: .7;
}

.frm-03__prow b {
  font-size: .85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: .04em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.frm-03__field {
  display: grid;
  gap: .4rem;
}

.frm-03__field label {
  font-size: .85rem;
  font-weight: 600;
}

.frm-03__row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.frm-03 input[type="text"] {
  width: 100%;
  min-height: 3rem;
  padding: .7rem .95rem;
  border-radius: .75rem;
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  font-size: 1rem;
  transition: border-color .2s, box-shadow .25s var(--ease);
}

.frm-03 input[inputmode="numeric"] {
  font-family: var(--mono);
  font-size: .95rem;
  letter-spacing: .02em;
}

.frm-03 ::placeholder {
  color: color-mix(in oklab,var(--muted) 70%,transparent);
}

.frm-03 input:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 4px color-mix(in oklab,var(--accent) 18%,transparent);
}

.frm-03 input:user-invalid {
  border-color: var(--bad);
}

.frm-03__numwrap {
  position: relative;
}

.frm-03 .frm-03__numwrap input {
  padding-right: 4.25rem;
}

.frm-03__badge {
  position: absolute;
  right: .6rem;
  top: 50%;
  translate: 0 -50%;
  font-size: .65rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: .3rem .5rem;
  border-radius: .35rem;
  background: var(--sum);
  color: var(--muted);
  border: 1px solid var(--line);
  opacity: 0;
  scale: .8;
  transition: opacity .25s, scale .3s var(--ease);
}

.frm-03:not([data-brand="none"]) .frm-03__badge {
  opacity: 1;
  scale: 1;
}

.frm-03__save {
  display: flex;
  align-items: center;
  gap: .6rem;
  font-size: .9rem;
  color: var(--muted);
  cursor: pointer;
  min-height: 2.75rem;
}

.frm-03__save input {
  width: 1.1rem;
  height: 1.1rem;
  accent-color: var(--accent);
  margin: 0;
}

.frm-03__paybtn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: .6rem;
  min-height: 3.4rem;
  border: 0;
  border-radius: .9rem;
  cursor: pointer;
  font: inherit;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--on-accent);
  background: var(--accent);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.2), 0 12px 26px -12px color-mix(in oklab,var(--accent) 90%,black);
  transition: translate .2s var(--ease), filter .2s;
}

.frm-03__paybtn svg {
  width: 1.15rem;
  height: 1.15rem;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
}

.frm-03__paybtn b {
  font-variant-numeric: tabular-nums;
}

.frm-03__paybtn:hover {
  translate: 0 -2px;
  filter: brightness(1.07);
}

.frm-03__paybtn:active {
  translate: 0 1px;
}

.frm-03__paybtn:focus-visible {
  outline: 2px solid var(--ink);
  outline-offset: 3px;
}

.frm-03__paybtn[aria-busy="true"] {
  pointer-events: none;
  filter: saturate(.6);
}

.frm-03__secure {
  margin: 0;
  font-size: .8rem;
  color: var(--muted);
  text-align: center;
}

.frm-03__items {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 1rem;
}

.frm-03__items li {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: .9rem;
  align-items: center;
}

.frm-03__items img {
  width: 4.5rem;
  height: 4.5rem;
  object-fit: cover;
  border-radius: .9rem;
  background: var(--line);
  border: 1px solid var(--line);
}

.frm-03__items b {
  display: block;
  font-size: .95rem;
}

.frm-03__items small {
  display: block;
  color: var(--muted);
  font-size: .8rem;
  margin: .1rem 0 .4rem;
}

.frm-03__price {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.frm-03__qty {
  display: inline-flex;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: .6rem;
  background: var(--surface);
}

.frm-03__qty button {
  width: 2.25rem;
  height: 2.25rem;
  border: 0;
  background: transparent;
  color: var(--ink);
  font-size: 1.1rem;
  cursor: pointer;
  border-radius: .55rem;
}

.frm-03__qty button:hover {
  background: var(--sum);
}

.frm-03__qty button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.frm-03__qty output {
  min-width: 1.75rem;
  text-align: center;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.frm-03__promo {
  display: flex;
  gap: .5rem;
}

.frm-03__promo input {
  flex: 1;
  min-width: 0;
  text-transform: uppercase;
}

.frm-03__promo input::placeholder {
  text-transform: none;
}

.frm-03__apply {
  min-height: 3rem;
  padding: 0 1.1rem;
  border-radius: .75rem;
  border: 1px solid var(--line);
  background: var(--surface);
  color: var(--ink);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.frm-03__apply:hover {
  border-color: var(--ink);
}

.frm-03__apply:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.frm-03__codemsg {
  margin: -.5rem 0 0;
  font-size: .8rem;
  min-height: 1em;
}

.frm-03__codemsg[data-ok="true"] {
  color: var(--ok);
}

.frm-03__codemsg[data-ok="false"] {
  color: var(--bad);
}

.frm-03__totals {
  margin: 0;
  display: grid;
  gap: .6rem;
  padding-top: 1rem;
  border-top: 1px solid var(--line);
}

.frm-03__totals div {
  display: flex;
  justify-content: space-between;
  font-size: .92rem;
}

.frm-03__totals dt {
  color: var(--muted);
}

.frm-03__totals dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}

.frm-03__disc {
  color: var(--ok);
}

.frm-03__disc dt {
  color: inherit !important;
}

.frm-03:not(.has-disc) .frm-03__disc {
  display: none !important;
}

.frm-03__grand {
  padding-top: .8rem;
  border-top: 1px dashed var(--line);
  font-size: 1.15rem !important;
  font-weight: 700;
}

.frm-03__grand dt {
  color: var(--ink) !important;
}

.frm-03__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .frm-03 * {
    transition: none !important;
    animation: none !important;
  }
}

@media (forced-colors: active) {
  .frm-03__face {
    background: Canvas;
    border: 1px solid CanvasText;
    color: CanvasText;
  }

  .frm-03__methods input:checked + span {
    background: Highlight;
    color: HighlightText;
  }

  .frm-03__paybtn {
    border: 1px solid ButtonText;
  }
}
/* Theme toggle — top-right of the demo. Ink-relative colours, so it suits light and dark. */

.frm-03 {
  position: relative;
  padding-top: 72px;
  box-sizing: border-box;
}

.frm-03__theme {
  position: absolute;
  top: 16px;
  right: 16px;
  z-index: 20;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border-radius: 999px;
  border: 1px solid color-mix(in srgb, currentColor 22%, transparent);
  background: color-mix(in srgb, currentColor 8%, transparent);
  color: inherit;
  cursor: pointer;
  -webkit-backdrop-filter: blur(8px);
  backdrop-filter: blur(8px);
  transition: background-color .2s, transform .2s;
}

.frm-03__theme:hover {
  background: color-mix(in srgb, currentColor 14%, transparent);
}

.frm-03__theme:active {
  transform: scale(.94);
}

.frm-03__theme:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
}

.frm-03__theme svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.frm-03__theme .frm-03__sun,
.frm-03__theme[aria-pressed="true"] .frm-03__moon {
  display: none;
}

.frm-03__theme[aria-pressed="true"] .frm-03__sun {
